from pathlib import Path
p=Path('tools/test-work-center-browser.mjs');s=p.read_text(encoding='utf-8')
s=s.replace("context:{user:'tecnico'}", "context:{user:'tecnico',admin:true,usuarios:[{Usuario:'tecnico',NombreUsuario:'Técnico'}],empleados:[]}",1)
s=s.replace("minutos:45,trabajos:","minutos:45,calificaciones:{resumen:{cantidad:1,promedio:4.67},detalle:[{fecha:'2026-10-16 11:10:00',code:'SOP-2026-000001',usuario:'tecnico',rapidez:5,trato:4,solucion:5,comentario:'Atención excelente'}]},trabajos:",1)
marker="await page.screenshot({path:'output/work-center-desktop.png',fullPage:true});"
checks="""assert.equal(await page.getByRole('button',{name:'Archivar terminada',exact:true}).count(),1,'only completed internal task offers archive');await page.evaluate(()=>{window.archiveEvents=[];vm.$children[0].$on('task-archive',event=>archiveEvents.push({id:event.task.Id,restore:event.restore}));});await page.getByRole('button',{name:'Archivar terminada',exact:true}).click();assert.deepEqual(await page.evaluate(()=>archiveEvents),[{id:1,restore:false}]);await page.evaluate(()=>vm.$set(vm.tasks[0],'Archivada',1));await page.getByRole('button',{name:'Restaurar',exact:true}).click();assert.deepEqual(await page.evaluate(()=>archiveEvents[1]),{id:1,restore:true});assert((await page.locator('.work-kpis').innerText()).includes('4.7 / 5'));await page.getByText('Calificaciones de los clientes',{exact:true}).click();assert((await page.locator('.work-history').first().innerText()).includes('Atención excelente'));await page.locator('.work-date-filters select').selectOption('u:tecnico');await page.getByRole('button',{name:'Consultar período',exact:true}).click();await page.waitForFunction(()=>calls.some(call=>call.technician_user==='tecnico'));"""
s=s.replace(marker,checks+marker,1)
